(function(){var M={"hero.jpg":"data:image/jpeg;base64,","logo.jpg":"data:image/jpeg;base64,"};document.querySelectorAll("[data-img]").forEach(function(e){e.src=M[e.getAttribute("data-img")]});document.querySelectorAll("[data-hero]").forEach(function(e){e.style.setProperty("--hero","url("+M[e.getAttribute("data-hero")]+")");e.style.setProperty("--hpos",e.getAttribute("data-pos")||"center 35%")})})();
